761	    THREE.MathUtils.lerp(A.p[1],B.p[1],a),
762	    THREE.MathUtils.lerp(A.p[2],B.p[2],a));
763	  const tx=THREE.MathUtils.lerp(A.t[0],B.t[0],a),
764	        ty=THREE.MathUtils.lerp(A.t[1],B.t[1],a),
765	        tz=THREE.MathUtils.lerp(A.t[2],B.t[2],a);
766	  // mouse parallax
767	  camera.position.x+=mouse.x*0.5; camera.position.y+=mouse.y*0.25;
768	  camera.lookAt(tx,ty,tz);
